for lang in ("en", "de"):
    html = src
    for old, new in structural(lang) + T[lang]:
        if old not in html:
            if old in OBSOLETE:
                continue
            print(f"[{lang}] NIET GEVONDEN: {old[:90]}")
            ok = False
            continue
        html = html.replace(old, new)
    out = ROOT / lang / "index.html"
    out.parent.mkdir(exist_ok=True)
    out.write_text(html, encoding="utf-8")
